1	// villa-haiku: the palette (palette.json), the site (plan.md SITE, OPENINGS, ROOMS), and one helper per VOCABULARY item.
2	// Every helper takes the grid first, then plan.md's parameters. Coordinates are PLAN coordinates: x 0..35, y 0..9,
3	// z 0..47, the street at z -4..-1 (SiteGrid shifts them into the file). Runs and floors are [x0, z0, x1, z1]
4	// (inclusive); solids are [x0, y0, z0, x1, y1, z1] (inclusive).
5	import { readFileSync } from "node:fs";
6	import { Grid, B, DIRS, carve, roof } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
7	
8	// ---- site: plan.md SITE; rooms.json is the plan's room list ----------------------------------------------------------
9	export const SITE = { w: 36, h: 10, d: 48, street: 4 };       // street: plan z -4..-1 is file z 0..3
10	const ROOMS_FILE = JSON.parse(readFileSync(new URL("./rooms.json", import.meta.url), "utf8"));
11	export const ENTRANCE = ROOMS_FILE.entrance;                  // [17, 1, -1]: on the street paving
12	export const ROOMS = ROOMS_FILE.rooms;                        // [{ name, box: [x0, y0, z0, x1, y1, z1] }]
13	export const POCKET = [16, 2, 0, 19, 5, 0];                   // fauces recess carved in the street wall
14	export const FAUCES_DOOR_X = 17;                              // leaves at x17 and x18, z=1
15	export const SHOP_OPENINGS = [[2, 5], [10, 13], [22, 25], [30, 33]];     // x0..x1 at z=0, y2..4
16	export const STREET_SHUTTERS = [1, 6, 9, 14, 21, 26, 29, 34];            // wall cells beside the shop openings
17	export const PEDIMENT = [16, 19, 0];                          // x0, x1, z of the fauces gable
18	export const IMPLUVIUM = [15, 12, 20, 17];                    // 6x6 with its rim
19	export const FOUNTAIN = [15, 31, 20, 36];                     // 6x6 with its rim
20	export const COURT = [12, 30, 23, 37];                        // grass court inside the colonnade
21	export const STATUES = [[13, 33], [22, 33]];
22	export const ATRIUM_LAMPS = [[10, 9], [25, 9], [10, 20], [25, 20]];
23	export const POCKET_LAMPS = [[16, 0], [19, 0]];
24	export const STREET_LAMPS = [[13, -2], [22, -2]];             // base y1 (on the paving)
25	export const WALKWAY_POTS = [[9, 28], [26, 28], [9, 39], [26, 39]];
26	export const STREET_PAVING = [12, -4, 23, -1];
27	
28	/** The site grid: plan coordinates in, a file whose z starts at the street (nbt cannot hold negative z). */
29	export class SiteGrid extends Grid {
30	  constructor() { super([SITE.w, SITE.h, SITE.d + SITE.street]); }
31	  set(x, y, z, block, state, nbt) { return super.set(x, y, z + SITE.street, block, state, nbt); }
32	  get(x, y, z) { return super.get(x, y, z + SITE.street); }
33	  unset(x, y, z) { return super.unset(x, y, z + SITE.street); }
34	}
35	export const siteGrid = () => new SiteGrid();
36	
37	// ---- palette: plan.md PALETTE (every id is in palette.json) ----------------------------------------------------------
38	export const WALL = "smooth_quartz";
39	export const DADO = "red_terracotta";
40	export const PILLAR = "quartz_pillar";
41	export const QUARTZ_SLAB = "quartz_slab";
42	export const QUARTZ_BLOCK = "quartz_block";
43	export const PLINTH = "polished_andesite";
44	export const MOSAIC_FIELD = "white_terracotta";
45	export const MOSAIC_EDGE = "black_terracotta";
46	export const GRASS = "grass_block";
47	export const PATH = "smooth_stone";
48	export const PATH_SLAB = "smooth_stone_slab";
49	export const HEDGE = "azalea_leaves";
50	export const ROSE = "rose_bush";
51	export const CORNFLOWER = "cornflower";
52	export const POPPY = "poppy";
53	export const RIM_SLAB = "smooth_quartz_slab";
54	export const WATER = "water";
55	export const STATUE = "oxidized_copper";
56	export const STATUE_CAP = "oxidized_cut_copper_slab";
57	export const DOOR = "dark_oak_door";
58	export const SHUTTER = "dark_oak_trapdoor";
59	export const BARS = "iron_bars";
60	export const LANTERN = "lantern";
61	export const POT_FERN = "potted_fern";
62	export const POT_AZALEA = "potted_azalea_bush";
63	export const ROOF_TILE = "bricks";
64	export const ROOF_TILE_RED = "red_nether_bricks";
65	export const PEDIMENT_STAIRS = "quartz_stairs";
66	export const COUCH = "dark_oak_stairs";
67	export const CUSHION = "red_carpet";
68	export const TABLE_SLAB = "dark_oak_slab";
69	export const HEARTH = "campfire";
70	export const STONE_BRICKS = "stone_bricks";
71	export const SMOKER = "smoker";
72	export const BARREL = "barrel";
73	export const BED = "red_bed";
74	export const BOOKSHELF = "bookshelf";
75	export const LECTERN = "lectern";
76	// the roof tool's RoofTile: field 3 : 2 red, eave bricks, ridge quartz_slab, verge quartz_block
77	export const ROOF_MATERIAL = { mix: [[ROOF_TILE, 3], [ROOF_TILE_RED, 2]], eave: ROOF_TILE, ridge: QUARTZ_SLAB, verge: QUARTZ_BLOCK };
78	
79	// ---- helpers ---------------------------------------------------------------------------------------------------------
80	const level = ([x0, z0, x1, z1], y) => [[x0, y, z0], [x1, y, z1]];      // a flat box at one height, for g.fill
81	
82	/** plaster: a wall run: smooth_quartz at y2..top, red_terracotta dado at y2..3. top 5 for a plain wall; higher where a roof's high side is walled. */
83	export function plaster(g, run, top = 5) {
84	  g.fill([run[0], 2, run[1]], [run[2], top, run[3]], WALL);
85	  g.fill([run[0], 2, run[1]], [run[2], 3, run[3]], DADO);
86	  return g;
87	}
88	
89	/** mosaicFloor: the floor at y1 of a box: white_terracotta field, black_terracotta border one cell in from each wall. */
90	export function mosaicFloor(g, [x0, z0, x1, z1]) {
91	  g.fill(...level([x0, z0, x1, z1], 1), MOSAIC_FIELD);
92	  for (const [a, b, c, d] of [[x0, z0, x1, z0], [x0, z1, x1, z1], [x0, z0, x0, z1], [x1, z0, x1, z1]])
93	    g.fill([a, 1, b], [c, 1, d], MOSAIC_EDGE);
94	  return g;
95	}
96	
97	/** doorway: one door in the wall cell (x, z): dark_oak_door lower y2 + upper y3 (hinge left); quartz_block jambs at y2..3 beside it; smooth_quartz lintel at y4..5. axis = the way the wall runs: "z" (an x-wall) or "x" (a z-wall). */
98	export function doorway(g, x, z, axis = "z") {
99	  const facing = axis === "z" ? "east" : "south";
100	  const [jx, jz] = axis === "z" ? [0, 1] : [1, 0];
101	  g.set(x, 2, z, ...B.door("dark_oak", facing, "lower", "left"));
102	  g.set(x, 3, z, ...B.door("dark_oak", facing, "upper", "left"));
103	  for (const s of [-1, 1]) g.fill([x + s * jx, 2, z + s * jz], [x + s * jx, 3, z + s * jz], QUARTZ_BLOCK);
104	  g.fill([x, 4, z], [x, 5, z], WALL);
105	  return g;
106	}
107	
108	/** doorwayFacing: the fauces door, two leaves at x and x+1 in the z wall, facing south, hinges outside; quartz_block jambs at x-1 and x+2; smooth_quartz lintel at y4..5 over both leaves. */
109	export function doorwayFacing(g, x, z) {
110	  g.set(x, 2, z, ...B.door("dark_oak", "south", "lower", "left"));
111	  g.set(x, 3, z, ...B.door("dark_oak", "south", "upper", "left"));
112	  g.set(x + 1, 2, z, ...B.door("dark_oak", "south", "lower", "right"));
113	  g.set(x + 1, 3, z, ...B.door("dark_oak", "south", "upper", "right"));
114	  for (const jx of [x - 1, x + 2]) g.fill([jx, 2, z], [jx, 3, z], QUARTZ_BLOCK);
115	  g.fill([x, 4, z], [x + 1, 5, z], WALL);
116	  return g;
117	}
118	
119	/** opening: a box in a wall carved to air. box = [x0, y0, z0, x1, y1, z1]. */
120	export function opening(g, box) {
121	  return carve(g, box.slice(0, 3), box.slice(3, 6));
122	}
123	
124	/** shutter: open dark_oak_trapdoors on the wall cells x, z from y0 to y1; facing = the side toward the opening. */
125	export function shutter(g, x, y0, y1, z, facing) {
126	  for (let y = y0; y <= y1; y++) g.set(x, y, z, ...B.trapdoor("dark_oak", facing, "bottom", true));
127	  return g;
128	}
129	
130	/** window: iron_bars at y3 and y4 in the wall cell (x, z). */
131	export function window(g, x, z) {
132	  g.fill([x, 3, z], [x, 4, z], BARS);
133	  return g;
134	}
135	
136	/** shopOpening: a street opening x0..x1 at z=0 carved to air at y2..4; smooth_quartz counter at z=1, y2; open shutters on the cells x0-1 and x1+1. */
137	export function shopOpening(g, x0, x1) {
138	  carve(g, [x0, 2, 0], [x1, 4, 0]);
139	  g.fill([x0, 2, 1], [x1, 2, 1], WALL);
140	  shutter(g, x0 - 1, 2, 4, 0, "east");
141	  shutter(g, x1 + 1, 2, 4, 0, "west");
142	  return g;
143	}
144	
145	/** column: a colonnade column at (x, z): quartz_pillar axis y at y2..4; quartz_slab bottom capital at y5. */
146	export function column(g, x, z) {
147	  g.fill([x, 2, z], [x, 4, z], PILLAR, { axis: "y" });
148	  g.set(x, 5, z, ...B.slab("quartz", "bottom"));
149	  return g;
150	}
151	
152	/** lamp: a standing lamp at (x, z): quartz_pillar axis y at y=base (2; 1 for the street lamps), a lantern hanging=false on top. */
153	export function lamp(g, x, z, base = 2) {
154	  g.set(x, base, z, ...B.pillar(PILLAR, "y"));
155	  g.set(x, base + 1, z, ...B.lantern(false));
156	  return g;
157	}
158	
159	const POT_KINDS = { fern: POT_FERN, azalea: POT_AZALEA, [POT_FERN]: POT_FERN, [POT_AZALEA]: POT_AZALEA };
160	/** pot: a potted plant at y2 on the floor: kind "fern" or "azalea" (the potted block is the pot). */
161	export function pot(g, x, z, kind = "fern") {
162	  if (!POT_KINDS[kind]) throw new Error(`pot: unknown kind ${kind}`);
163	  g.set(x, 2, z, POT_KINDS[kind]);
164	  return g;
165	}
166	
167	/** hedge: a row of 1-high azalea_leaves (persistent) at y2 over the run [x0, z0, x1, z1]. */
168	export function hedge(g, run) {
169	  g.fill([run[0], 2, run[1]], [run[2], 2, run[3]], HEDGE, { persistent: "true" });
170	  return g;
171	}
172	
173	/** bed: a planted bed on the court box: grass at y1; rose_bush (2 high) at the four corners; cornflower and poppy at y2 on the rest, in a checker. */
174	export function bed(g, [x0, z0, x1, z1]) {
175	  g.fill(...level([x0, z0, x1, z1], 1), GRASS);
176	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
177	    const corner = (x === x0 || x === x1) && (z === z0 || z === z1);
178	    if (corner) {
179	      g.set(x, 2, z, ROSE, { half: "lower" });
180	      g.set(x, 3, z, ROSE, { half: "upper" });
181	    } else g.set(x, 2, z, (x + z) % 2 ? CORNFLOWER : POPPY);
182	  }
183	  return g;
184	}
185	
186	/** couch: a run of three cells (a line): dark_oak_stairs at y2 facing the table, red_carpet at y2 in front of each. facing = the way the seats face. */
187	export function couch(g, [x0, z0, x1, z1], facing) {
188	  const [dx, , dz] = DIRS[facing];
189	  for (let x = Math.min(x0, x1); x <= Math.max(x0, x1); x++) for (let z = Math.min(z0, z1); z <= Math.max(z0, z1); z++) {
190	    g.set(x, 2, z, ...B.stairs("dark_oak", facing));
191	    g.set(x + dx, 2, z + dz, CUSHION);
192	  }
193	  return g;
194	}
195	
196	/** statue: polished_andesite plinth at y2; oxidized_copper figure at y3..4; oxidized_cut_copper_slab cap (bottom) at y5. */
197	export function statue(g, x, z) {
198	  g.set(x, 2, z, PLINTH);
199	  g.fill([x, 3, z], [x, 4, z], STATUE);
200	  g.set(x, 5, z, ...B.slab("oxidized_cut_copper", "bottom"));
201	  return g;
202	}
203	
204	/** basin: the 6x6 box at y1: smooth_quartz_slab bottom around the ring, water inside. */
205	function basin(g, [x0, z0, x1, z1]) {
206	  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
207	    const rim = x === x0 || x === x1 || z === z0 || z === z1;
208	    if (rim) g.set(x, 1, z, ...B.slab("smooth_quartz", "bottom"));
209	    else g.set(x, 1, z, WATER);
210	  }
211	  return g;
212	}
213	
214	/** impluvium: the rain pool in the 6x6 box: rim smooth_quartz_slab at y1, water 4x4 at y1 inside. */
215	export function impluvium(g, box) {
216	  return basin(g, box);
217	}
218	
219	/** fountain: the court fountain in the 6x6 box: the basin as impluvium; quartz_block column 2x2 at y2..3 in the centre; water on top at y4 over the centre's first cell. */
220	export function fountain(g, box) {
221	  basin(g, box);
222	  const cx = box[0] + 2, cz = box[1] + 2;                    // x17..18 z33..34 for the box at x15 z31
223	  g.fill([cx, 2, cz], [cx + 1, 3, cz + 1], QUARTZ_BLOCK);
224	  g.set(cx, 4, cz, WATER);
225	  return g;
226	}
227	
228	/** roofBand: one shed band over rects (a rect [x0, z0, x1, z1] or a union of them), low = the low side. Eave course y6, palette RoofTile; the soffit is the tile (no timber fascia: plan.md names no fascia). Returns the roof tool's report. */
229	export function roofBand(g, rects, low) {
230	  return roof(g, rects, "shed", { y: 6, low, material: ROOF_MATERIAL, soffit: ROOF_TILE, edges: { fascia: false, barge: false } });
231	}
232	
233	/** pediment: the fauces gable over the pocket: quartz_stairs at y6 x0..x1 and y7 x0+1..x1-1 at z, turned to the street (facing north). */
234	export function pediment(g, x0, x1, z) {
235	  for (let x = x0; x <= x1; x++) g.set(x, 6, z, ...B.stairs("quartz", "north"));
236	  for (let x = x0 + 1; x <= x1 - 1; x++) g.set(x, 7, z, ...B.stairs("quartz", "north"));
237	  return g;
238	}
239	
240	/** streetPaving: the approach: stone_bricks at y0 over the box; the edge row (z = z1, the row at z=-1) as smooth_stone_slab bottom. */
241	export function streetPaving(g, [x0, z0, x1, z1]) {
242	  g.fill([x0, 0, z0], [x1, 0, z1], STONE_BRICKS);
243	  for (let x = x0; x <= x1; x++) g.set(x, 0, z1, ...B.slab("smooth_stone", "bottom"));
244	  return g;
245	}
